import {
    Table,
    DomainPathColumn,
    ReferenceColumn,
    StringColumn,
    BooleanColumn,
    DecimalColumn,
    ListColumn,
    IntegerColumn,
    DomainIdColumn,
    DateColumn,
    DateTimeColumn,
    GenericColumn,
    SystemClassNameColumn,
    GuidColumn,
    UserRolesColumn,
    JsonColumn,
    ChoiceColumn,
    BasicImageColumn,
} from '@servicenow/sdk/core'

export const kb_knowledge = Table({
    actions: ['read', 'update', 'create'],
    allowClientScripts: true,
    allowNewFields: true,
    allowUiActions: true,
    allowWebServiceAccess: true,
    attributes: {
        'all_tables.text_index_translations': true,
        attachment_index: true,
        document_viewer_audit: 'all',
        global_search_config_handler: 'KnowledgeArticle',
        text_index_attachment_displayed: true,
        text_index_enable_idf: true,
        text_index_filter_junk: false,
        use_document_viewer: true,
    },
    audit: true,
    autoNumber: {
        number: 10000,
        prefix: 'KB',
    },
    display: 'display_number',
    extensible: true,
    label: 'Knowledge',
    name: 'kb_knowledge',
    schema: {
        sys_domain_path: DomainPathColumn({
            attributes: {
                case_sensitive: true,
            },
            default: '/',
            label: 'Domain Path',
        }),
        taxonomy_topic: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: [
                {
                    hint: 'primary taxonomy topic for the item',
                    label: 'Taxonomy topic',
                    plural: 'Taxonomy topics',
                    language: 'en',
                },
            ],
            referenceTable: 'topic',
        }),
        short_description: StringColumn({
            attributes: {
                ts_weight: '10',
            },
            label: [
                {
                    hint: 'Title of the article',
                    label: 'Short description',
                    plural: 'Short descriptions',
                    language: 'en',
                },
            ],
            mandatory: true,
            maxLength: 100,
        }),
        author: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            default: 'javascript:gs.getUserID()',
            label: [
                {
                    hint: 'Primary author of this article',
                    label: 'Author',
                    plural: 'Authors',
                    language: 'en',
                },
            ],
            referenceTable: 'sys_user',
        }),
        disable_suggesting: BooleanColumn({
            default: false,
            label: [
                {
                    hint: "Removes 'Flag Article' button from the article view",
                    label: 'Disable suggesting',
                    plural: 'Disable suggestings',
                    language: 'en',
                },
            ],
        }),
        generated_with_now_assist: BooleanColumn({
            default: false,
            label: 'Generated With Now Assist',
            readOnly: true,
        }),
        sys_created_by: StringColumn({
            label: [
                {
                    label: 'Created by',
                    plural: 'Created by',
                    language: 'en',
                },
            ],
        }),
        cmdb_ci: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: 'Configuration item',
            referenceTable: 'cmdb_ci',
        }),
        meta: StringColumn({
            attributes: {
                ts_weight: '10',
            },
            label: [
                {
                    hint: 'Additional text indexed for search purposes, not shown when viewing article',
                    label: 'Meta',
                    plural: 'Metas',
                    language: 'en',
                },
            ],
            maxLength: 4000,
        }),
        rating: DecimalColumn({
            label: [
                {
                    hint: 'Average rating based on user feedback',
                    label: 'Rating',
                    plural: 'Ratings',
                    language: 'en',
                },
            ],
            maxLength: 15,
            readOnly: true,
        }),
        can_read_user_criteria: ListColumn({
            attributes: {
                no_sort: true,
                slushbucket_ref_no_expand: true,
            },
            label: 'Can Read',
            maxLength: 1024,
            referenceTable: 'user_criteria',
            referenceQual: 'active=true^EQ',
        }),
        sys_mod_count: IntegerColumn({
            label: [
                {
                    label: 'Updates',
                    plural: 'Updates',
                    language: 'en',
                },
            ],
        }),
        category: StringColumn({
            dropdown: 'dropdown_with_none',
            dependent: 'topic',
            label: [
                {
                    hint: 'Lower level of article categorization - Topics can have multiple Categories',
                    label: 'Category',
                    plural: 'Categories',
                    language: 'en',
                },
            ],
        }),
        source: ReferenceColumn({
            attributes: {
                encode_utf8: false,
                readonly_clickthrough: true,
            },
            label: [
                {
                    hint: 'Task from which this article originated, if any',
                    label: 'Source task',
                    plural: 'Source tasks',
                    language: 'en',
                },
            ],
            referenceTable: 'task',
        }),
        kb_knowledge_base: ReferenceColumn({
            attributes: {
                readonly_clickthrough: true,
            },
            default: 'javascript:getDefaultKB()',
            label: 'Knowledge base',
            mandatory: true,
            referenceTable: 'kb_knowledge_base',
            referenceQual: 'javascript: new KnowledgeRefQualifiers().getCanContributeKBs(current.sys_class_name);',
        }),
        meta_description: StringColumn({
            attributes: {
                no_text_index: true,
            },
            label: 'Meta Description',
            maxLength: 1000,
        }),
        article_type: StringColumn({
            default: 'text',
            dropdown: 'dropdown_without_none',
            label: [
                {
                    hint: 'Type of article',
                    label: 'Article type',
                    plural: 'Article types',
                    language: 'en',
                },
            ],
        }),
        sys_domain: DomainIdColumn({
            default: 'global',
            label: [
                {
                    hint: 'Domain to which the article belongs',
                    label: 'Domain',
                    plural: 'Domains',
                    language: 'en',
                },
            ],
        }),
        retired: DateColumn({
            label: [
                {
                    hint: 'Date of retirement',
                    label: 'Retired',
                    plural: 'Retired',
                    language: 'en',
                },
            ],
            readOnly: true,
        }),
        replacement_article: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: [
                {
                    hint: 'Replacement article to this article after retirement.',
                    label: 'Replacement Article',
                    plural: 'Replacement Articles',
                    language: 'en',
                },
            ],
            readOnly: true,
            referenceTable: 'kb_knowledge',
        }),
        sys_updated_by: StringColumn({
            label: [
                {
                    label: 'Updated by',
                    plural: 'Updated by',
                    language: 'en',
                },
            ],
        }),
        scheduled_publish_date: DateTimeColumn({
            label: [
                {
                    hint: 'If specified, article will be published on that date and time',
                    label: 'Scheduled publish date',
                    plural: 'Scheduled publish dates',
                    language: 'en',
                },
            ],
        }),
        base_version: ReferenceColumn({
            attributes: {
                encode_utf8: false,
                readonly_clickthrough: true,
            },
            label: 'Base Version',
            readOnly: true,
            referenceTable: 'kb_knowledge',
        }),
        display_number: StringColumn({
            dynamicValueDefinitions: {
                type: 'calculated_value',
                calculatedValue: `(function calculatedFieldValue(current) {

	// Add your code here
	var version = '';
	if(current.version && !current.version.nil())
		version = ' v'+current.version.version;
	
	return current.number+version;  // return the calculated value

})(current);`,
            },
            label: 'Display number',
        }),
        latest_aqi: ReferenceColumn({
            attributes: {
                encode_utf8: false,
                readonly_clickthrough: true,
            },
            label: 'Latest AQI',
            readOnly: true,
            referenceTable: 'kb_article_checklist_summary',
        }),
        summary: ReferenceColumn({
            attributes: {
                encode_utf8: false,
                readonly_clickthrough: true,
            },
            label: 'Summary',
            readOnly: true,
            referenceTable: 'kb_knowledge_summary',
        }),
        revised_by: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: 'Revised By',
            readOnly: true,
            referenceTable: 'sys_user',
        }),
        article_id: StringColumn({
            label: 'Article ID',
            maxLength: 32,
            readOnly: true,
        }),
        version: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: 'Version',
            readOnly: true,
            referenceTable: 'kb_version',
        }),
        ownership_group: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: 'Ownership Group',
            referenceTable: 'sys_user_group',
            referenceQual: 'typeLIKE458de4f067671300dbfdbb2d07415ad6^EQ',
        }),
        latest: BooleanColumn({
            default: true,
            label: 'Latest',
            readOnly: true,
        }),
        published: DateColumn({
            label: [
                {
                    hint: 'Date article was published',
                    label: 'Published',
                    plural: 'Published',
                    language: 'en',
                },
            ],
        }),
        active: BooleanColumn({
            attributes: {
                ignore_filter_on_new: true,
            },
            default: true,
            label: [
                {
                    hint: 'Part of the active Knowledge Base',
                    label: 'Active',
                    plural: 'Active',
                    language: 'en',
                },
            ],
        }),
        display_attachments: BooleanColumn({
            default: false,
            label: [
                {
                    hint: "Display all attachments when viewing article - only relevant when 'Attachment link' is unchecked",
                    label: 'Display attachments',
                    plural: 'Display attachments',
                    language: 'en',
                },
            ],
        }),
        workflow_state: GenericColumn({
            attributes: {
                ignore_filter_on_new: true,
            },
            columnType: 'workflow',
            default: 'draft',
            dropdown: 'dropdown_with_none',
            label: [
                {
                    hint: 'Knowledge base workflow state',
                    label: 'Workflow',
                    plural: 'Workflows',
                    language: 'en',
                },
            ],
            maxLength: 80,
        }),
        sys_class_name: SystemClassNameColumn({
            default: 'javascript:current.getTableName();',
            dropdown: 'dropdown_without_none',
            label: 'Class',
            maxLength: 80,
        }),
        kb_category: ReferenceColumn({
            attributes: {
                encode_utf8: false,
                field_decorations: 'kb_category_reference_lookup',
            },
            label: 'Category',
            referenceTable: 'kb_category',
            referenceQual:
                'javascript: new global.GlobalKnowledgeUtil().getRefQualCategoryIdsForKB(current.kb_knowledge_base)',
        }),
        helpful_count: IntegerColumn({
            default: '0',
            label: [
                {
                    hint: 'Number of times this article has been helpful',
                    label: 'Helpful count',
                    plural: 'Helpful counts',
                    language: 'en',
                },
            ],
            readOnly: true,
        }),
        sys_id: GuidColumn({
            label: [
                {
                    label: 'Sys ID',
                    plural: 'Sys IDs',
                    language: 'en',
                },
            ],
            primary: true,
        }),
        roles: UserRolesColumn({
            array: true,
            attributes: {
                record_watcher_blacklist: true,
            },
            label: [
                {
                    hint: 'Roles allowed to view or search for article - if empty, all users can see',
                    label: 'Roles',
                    plural: 'Roles',
                    language: 'en',
                },
            ],
        }),
        flagged: BooleanColumn({
            label: [
                {
                    hint: 'Flagged by users as incorrect or incomplete, true if any Feedback record for this article is flagged',
                    label: 'Flagged',
                    plural: 'Flagged',
                    language: 'en',
                },
            ],
        }),
        disable_commenting: BooleanColumn({
            default: false,
            label: [
                {
                    hint: 'Disables writing comments to an article',
                    label: 'Disable commenting',
                    plural: 'Disable commentings',
                    language: 'en',
                },
            ],
        }),
        instrumentation_metadata: JsonColumn({
            label: 'Instrumentation metadata',
            maxLength: 8000,
            readOnly: true,
        }),
        sys_updated_on: DateTimeColumn({
            label: [
                {
                    label: 'Updated',
                    plural: 'Updated',
                    language: 'en',
                },
            ],
        }),
        text: GenericColumn({
            attributes: {
                'editor.height': '300',
                'editor.plugins':
                    'table link image media codemirror lists advlist fullscreen charmap directionality emoticons insertdatetime nonbreaking pagebreak searchreplace wordcount anchor tableofcontents codesample visualblocks visualchars compat3x autolink align_listitems tinymcespellchecker accordion editimage a11ychecker readonlynoborder',
                'editor.toolbar':
                    'fontfamily fontsize | bold italic underline strikethrough forecolor backcolor pastetext removeformat | blocks searchreplace undo redo spellchecker | bullist numlist outdent indent alignleft aligncenter alignright | tableofcontents table link unlink a11ycheck anchor accordion insertdatetime | image media codesample | code fullscreen',
                encode_utf8: false,
                serializer: 'com.glide.script.TranslatedTextXMLSerializer',
            },
            columnType: 'translated_html',
            label: [
                {
                    hint: 'Body of the article',
                    label: 'Article body',
                    plural: 'Article body',
                    language: 'en',
                },
            ],
            maxLength: 65000,
        }),
        use_count: IntegerColumn({
            default: '0',
            label: [
                {
                    hint: 'Number of times article has been attached to a task',
                    label: 'Use count',
                    plural: 'Use counts',
                    language: 'en',
                },
            ],
            readOnly: true,
        }),
        view_as_allowed: BooleanColumn({
            default: true,
            label: [
                {
                    hint: 'Allow a permitted user to search and view this article as another user',
                    label: 'View as allowed',
                    plural: 'View as allowed',
                    language: 'en',
                },
            ],
        }),
        editor_type: ChoiceColumn({
            default: 'TinyMCE',
            dropdown: 'dropdown_without_none',
            label: 'Editor Type',
        }),
        sys_created_on: DateTimeColumn({
            label: [
                {
                    label: 'Created',
                    plural: 'Created',
                    language: 'en',
                },
            ],
        }),
        topic: StringColumn({
            default: 'General',
            dropdown: 'dropdown_without_none',
            label: [
                {
                    hint: 'Higher level of article categorization - Topics can have multiple Categories',
                    label: 'Topic',
                    plural: 'Topics',
                    language: 'en',
                },
            ],
        }),
        sys_view_count: IntegerColumn({
            default: '0',
            label: [
                {
                    hint: 'Number of times this article has been viewed',
                    label: 'View count',
                    plural: 'View counts',
                    language: 'en',
                },
            ],
            readOnly: true,
        }),
        description: StringColumn({
            label: [
                {
                    hint: 'Purpose of the article, not displayed in the Knowledge Base. This field can be used for internal notes.',
                    label: 'Description',
                    plural: 'Descriptions',
                    language: 'en',
                },
            ],
            maxLength: 4000,
        }),
        cannot_read_user_criteria: ListColumn({
            attributes: {
                no_sort: true,
                slushbucket_ref_no_expand: true,
            },
            label: 'Cannot Read',
            maxLength: 1024,
            referenceTable: 'user_criteria',
            referenceQual: 'active=true^EQ',
        }),
        image: BasicImageColumn({
            attributes: {
                pdf_cell_type: 'basic_image',
            },
            label: [
                {
                    hint: 'Displayed next to article short description in Knowledge Base (optional)',
                    label: 'Image',
                    plural: 'Images',
                    language: 'en',
                },
            ],
            maxLength: 100,
        }),
        wiki: GenericColumn({
            attributes: {
                is_multi_text: true,
                preview_first: true,
                preview_selector: true,
                image_refs: true,
            },
            columnType: 'wiki_text',
            dependent: 'short_description',
            label: [
                {
                    label: 'Wiki',
                    plural: 'Wikis',
                    language: 'en',
                    url: 'http://docs.servicenow.com/?context=Wiki_Plugin',
                    urlTarget: '_blank',
                },
            ],
            maxLength: 65000,
            textIndex: true,
        }),
        number: StringColumn({
            attributes: {
                ignore_filter_on_new: true,
                ts_weight: '50',
            },
            default: 'javascript:getNextObjNumberPadded();',
            label: 'Number',
            readOnly: true,
        }),
        valid_to: DateColumn({
            default:
                "javascript: current.kb_knowledge_base ? new global.KBCommon().getDefaultValidToDateFromCurrentDate(current.kb_knowledge_base) : '';",
            label: [
                {
                    hint: 'After this date, article will not appear in the Knowledge Base or be returned in search results',
                    label: 'Valid to',
                    plural: 'Valid to',
                    language: 'en',
                },
            ],
        }),
        direct: BooleanColumn({
            default: false,
            label: [
                {
                    hint: 'Clicking an article downloads its attachment instead of opening it in normal article view',
                    label: 'Attachment link',
                    plural: 'Attachment links',
                    language: 'en',
                },
            ],
        }),
    },
    textIndex: true,
})
